export type PicrossHints = {
  rows: number[][];
  columns: number[][];
};

// -1 = unknown, 0 = empty, 1 = filled
export type SolverCell = -1 | 0 | 1;
export type SolverGrid = SolverCell[][];

export type PicrossSolveResult = {
  // Number of solutions found, capped at 2 ("2" means "2 or more")
  solutionCount: 0 | 1 | 2;
  // True when line logic alone fully solves the puzzle (no guessing needed)
  logicSolvable: boolean;
  // First solution found (true = filled), if any
  solution: boolean[][] | null;
  // Cells still undetermined after line logic
  unknownCount: number;
};

/**
 * Solves a single line. Finds every cell that has the same value in all
 * arrangements of the clues consistent with the known cells.
 * Returns null if no arrangement fits.
 */
export function solveLine(
  line: SolverCell[],
  clues: number[],
): SolverCell[] | null {
  const n = line.length;
  const blocks = clues.filter((clue) => clue > 0);
  const m = blocks.length;

  const fits = (pos: number, k: number) => {
    const length = blocks[k]!;
    if (pos + length > n) return false;
    for (let i = pos; i < pos + length; i++) if (line[i] === 0) return false;
    return pos + length === n || line[pos + length] !== 1;
  };
  // Position after placing block k at pos, including the mandatory gap
  const after = (pos: number, k: number) => Math.min(pos + blocks[k]! + 1, n);

  // suffix[pos][k]: cells pos.. can hold blocks k.. validly
  const suffix = Array.from({ length: n + 1 }, () =>
    new Array<boolean>(m + 1).fill(false),
  );
  suffix[n]![m] = true;
  for (let pos = n - 1; pos >= 0; pos--) {
    for (let k = 0; k <= m; k++) {
      let ok = line[pos] !== 1 && suffix[pos + 1]![k]!;
      if (!ok && k < m && fits(pos, k)) ok = suffix[after(pos, k)]![k + 1]!;
      suffix[pos]![k] = ok;
    }
  }
  if (!suffix[0]![0]) return null;

  const reach = Array.from({ length: n + 1 }, () =>
    new Array<boolean>(m + 1).fill(false),
  );
  const canEmpty = new Array<boolean>(n).fill(false);
  const filledDiff = new Array<number>(n + 1).fill(0);
  reach[0]![0] = true;

  for (let pos = 0; pos < n; pos++) {
    for (let k = 0; k <= m; k++) {
      if (!reach[pos]![k]) continue;

      if (line[pos] !== 1 && suffix[pos + 1]![k]) {
        canEmpty[pos] = true;
        reach[pos + 1]![k] = true;
      }

      if (k < m && fits(pos, k)) {
        const next = after(pos, k);
        if (!suffix[next]![k + 1]) continue;
        filledDiff[pos]!++;
        filledDiff[pos + blocks[k]!]!--;
        if (pos + blocks[k]! < n) canEmpty[pos + blocks[k]!] = true;
        reach[next]![k + 1] = true;
      }
    }
  }

  const result: SolverCell[] = [];
  let filledCount = 0;
  for (let i = 0; i < n; i++) {
    filledCount += filledDiff[i]!;
    const canFill = filledCount > 0;
    if (canFill && !canEmpty[i]) result.push(1);
    else if (!canFill && canEmpty[i]) result.push(0);
    else if (!canFill && !canEmpty[i]) return null;
    else result.push(-1);
  }
  return result;
}

// Repeatedly solves rows and columns until nothing changes. False on contradiction.
function propagate(grid: SolverGrid, hints: PicrossHints): boolean {
  const height = grid.length;
  const width = grid[0]?.length ?? 0;
  let changed = true;

  while (changed) {
    changed = false;

    for (let y = 0; y < height; y++) {
      const solved = solveLine(grid[y]!, hints.rows[y] ?? []);
      if (!solved) return false;
      for (let x = 0; x < width; x++) {
        if (solved[x] !== grid[y]![x]) {
          grid[y]![x] = solved[x]!;
          changed = true;
        }
      }
    }

    for (let x = 0; x < width; x++) {
      const column = grid.map((row) => row[x]!);
      const solved = solveLine(column, hints.columns[x] ?? []);
      if (!solved) return false;
      for (let y = 0; y < height; y++) {
        if (solved[y] !== grid[y]![x]) {
          grid[y]![x] = solved[y]!;
          changed = true;
        }
      }
    }
  }
  return true;
}

function findUnknown(grid: SolverGrid) {
  for (let y = 0; y < grid.length; y++) {
    const x = grid[y]!.indexOf(-1);
    if (x !== -1) return { x, y };
  }
  return null;
}

/**
 * Solves a puzzle from its hints using line logic, falling back to
 * backtracking to determine whether the solution is unique.
 */
export function solvePicross(
  hints: PicrossHints,
  size: { width: number; height: number },
  initial?: SolverGrid,
  options: { logicOnly?: boolean; deadline?: number } = {},
): PicrossSolveResult {
  const start: SolverGrid =
    initial?.map((row) => [...row]) ??
    Array.from({ length: size.height }, () =>
      new Array<SolverCell>(size.width).fill(-1),
    );

  if (!propagate(start, hints)) {
    return {
      solutionCount: 0,
      logicSolvable: false,
      solution: null,
      unknownCount: size.width * size.height,
    };
  }
  const logicSolvable = findUnknown(start) === null;
  const unknownCount = start.reduce(
    (total, row) => total + row.filter((cell) => cell === -1).length,
    0,
  );

  let count = 0;
  let solution: boolean[][] | null = null;
  let timedOut = false;

  if (options.logicOnly && !logicSolvable) {
    return { solutionCount: 0, logicSolvable, solution: null, unknownCount };
  }

  const search = (grid: SolverGrid) => {
    if (options.deadline !== undefined && Date.now() > options.deadline) {
      timedOut = true;
    }
    if (timedOut) return;
    const cell = findUnknown(grid);
    if (!cell) {
      count++;
      solution ??= grid.map((row) => row.map((value) => value === 1));
      return;
    }
    for (const value of [1, 0] as const) {
      if (count >= 2 || timedOut) return;
      const copy = grid.map((row) => [...row]);
      copy[cell.y]![cell.x] = value;
      if (propagate(copy, hints)) search(copy);
    }
  };
  search(start);

  return {
    // An interrupted search can't vouch for uniqueness
    solutionCount: timedOut ? 0 : (Math.min(count, 2) as 0 | 1 | 2),
    logicSolvable,
    solution: timedOut ? null : solution,
    unknownCount,
  };
}

/**
 * Generates a random solution whose hints can be solved by line logic alone.
 * Stops after a time budget so large grids can't freeze the page; in that case
 * the candidate needing the least guessing is returned.
 */
export function generateSolvableSolution(
  size: { width: number; height: number },
  getHints: (solution: boolean[][]) => PicrossHints,
  maxAttempts = 300,
  timeBudgetMs = 750,
  random: () => number = Math.random,
): boolean[][] {
  const deadline = Date.now() + timeBudgetMs;
  let best: boolean[][] | null = null;
  let bestUnknown = Infinity;

  const finish = (solution: boolean[][]) => {
    // Re-solve with a short cap so the log never stalls large grids
    const result = solvePicross(getHints(solution), size, undefined, {
      deadline: Date.now() + 250,
    });
    console.log(
      `[picross] generated ${size.width}x${size.height}: logicSolvable=${result.logicSolvable}, solutionCount=${
        result.solutionCount === 0 && !result.logicSolvable
          ? "unknown (search timed out)"
          : result.solutionCount === 2
            ? "2+"
            : result.solutionCount
      }, unknownCells=${result.unknownCount}`,
    );
    return solution;
  };

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const density = 0.45 + random() * 0.15;
    const candidate = Array.from({ length: size.height }, () =>
      Array.from({ length: size.width }, () => random() < density),
    );
    const result = solvePicross(getHints(candidate), size, undefined, {
      logicOnly: true,
    });
    if (result.logicSolvable) return finish(candidate);
    if (result.unknownCount < bestUnknown) {
      best = candidate;
      bestUnknown = result.unknownCount;
    }
    if (Date.now() > deadline) break;
  }
  return finish(best!);
}
